sp_widget.client_script:
api.controller = function($window,$document,$timeout) {
    var c = this;

    c.selectedRecord = null;

    c.requestDropdownOpen = false;
    c.loadingRequestSuggestions = false;
    c.activeSuggestionIndex = -1;

    c.requestNumberSuggestions =
        angular.copy(
            c.data.requestNumberSuggestions || []
        );

    c.filteredRequestNumberSuggestions =
        angular.copy(
            c.requestNumberSuggestions
        );

    c.data.filters =
        c.data.filters || {
            requestNumber: "",
            courseType: "",
            courseFormat: "",
            country: ""
        };

    c.data.selectedStatus =
        c.data.selectedStatus || "manager";

    c.data.stageCounts =
        c.data.stageCounts || {
            manager: 0,
            pending_l2_approval: 0,
            pending_hr_review: 0
        };

    c.data.sortOrder =
        c.data.sortOrder || "asc";

    c.data.loading = false;
    c.data.downloading = false;

    c.clearMessages = function() {
        c.data.successMessage = "";
        c.data.errorMessage = "";
    };

    c.getSelectedApprovalLabel = function() {

        if (
            c.data.selectedStatus ==
            "pending_l2_approval"
        ) {
            return "Management L2";
        }

        if (
            c.data.selectedStatus ==
            "pending_hr_review"
        ) {
            return "HR Learning";
        }

        return "In-Company Manager";
    };

    c.getSelectedStatusLabel = function() {

        if (
            c.data.selectedStatus ==
            "pending_l2_approval"
        ) {
            return "Pending L2 Approval";
        }

        if (
            c.data.selectedStatus ==
            "pending_hr_review"
        ) {
            return "Pending HR Review";
        }

        return "Submitted / Pending Manager Approval";
    };

    c.getCommentsHeading = function() {

        if (
            c.data.selectedStatus ==
            "pending_l2_approval"
        ) {
            return "Management L2 Comments";
        }

        if (
            c.data.selectedStatus ==
            "pending_hr_review"
        ) {
            return "HR Learning Comments";
        }

        return "In-Company Manager Comments";
    };

    c.getRequestParameters = function(action) {

        return {
            action: action,

            selectedStatus:
                c.data.selectedStatus ||
                "manager",

            requestNumber:
                c.data.filters.requestNumber ||
                "",

            courseType:
                c.data.filters.courseType ||
                "",

            courseFormat:
                c.data.filters.courseFormat ||
                "",

            country:
                c.data.filters.country ||
                "",

            sortOrder:
                c.data.sortOrder ||
                "asc"
        };
    };

    c.updateResponse = function(response) {

        var result =
            response.data || {};

        c.data.records =
            result.records || [];

        c.data.countries =
            result.countries || [];

        c.data.courseTypes =
            result.courseTypes || [];

        c.data.courseFormats =
            result.courseFormats || [];

        c.data.stageCounts =
            result.stageCounts || {
                manager: 0,
                pending_l2_approval: 0,
                pending_hr_review: 0
            };

        c.data.successMessage =
            result.successMessage || "";

        c.data.errorMessage =
            result.errorMessage || "";

        if (result.filters) {
            c.data.filters =
                result.filters;
        }

        if (result.selectedStatus) {
            c.data.selectedStatus =
                result.selectedStatus;
        }

        if (result.sortOrder) {
            c.data.sortOrder =
                result.sortOrder;
        }

        c.requestNumberSuggestions =
            angular.copy(
                result.requestNumberSuggestions || []
            );

        c.filterRequestNumberSuggestions();

        c.requestDropdownOpen = false;
        c.activeSuggestionIndex = -1;
        c.selectedRecord = null;
    };

    /*
     * TYPEAHEAD METHODS
     */

    c.onRequestNumberChange = function() {

        c.filterRequestNumberSuggestions();

        c.requestDropdownOpen = true;
        c.activeSuggestionIndex = -1;
    };

    c.filterRequestNumberSuggestions = function() {

        var searchText =
            String(
                c.data.filters.requestNumber || ""
            ).toLowerCase();

        if (!searchText) {

            c.filteredRequestNumberSuggestions =
                angular.copy(
                    c.requestNumberSuggestions
                );

            return;
        }

        c.filteredRequestNumberSuggestions =
            c.requestNumberSuggestions.filter(
                function(suggestion) {

                    var number =
                        String(
                            suggestion.label || ""
                        ).toLowerCase();

                    var courseTitle =
                        String(
                            suggestion.courseTitle || ""
                        ).toLowerCase();

                    var employeeName =
                        String(
                            suggestion.employeeName || ""
                        ).toLowerCase();

                    return (
                        number.indexOf(searchText) > -1 ||
                        courseTitle.indexOf(searchText) > -1 ||
                        employeeName.indexOf(searchText) > -1
                    );
                }
            );
    };

    c.openRequestNumberSuggestions = function() {

        c.filterRequestNumberSuggestions();
        c.requestDropdownOpen = true;
        c.activeSuggestionIndex = -1;
    };

    c.toggleRequestNumberSuggestions = function(event) {

        if (event) {
            event.preventDefault();
            event.stopPropagation();
        }

        c.requestDropdownOpen =
            !c.requestDropdownOpen;

        if (c.requestDropdownOpen) {
            c.filterRequestNumberSuggestions();
            c.activeSuggestionIndex = -1;
        }
    };

    c.selectRequestNumber = function(
        suggestion,
        event
    ) {

        if (event) {
            event.preventDefault();
            event.stopPropagation();
        }

        if (!suggestion) {
            return;
        }

        c.data.filters.requestNumber =
            suggestion.value || suggestion.label || "";

        c.requestDropdownOpen = false;
        c.activeSuggestionIndex = -1;

        /*
         * Automatically search after selecting
         * a request number.
         */
        c.search();
    };

    c.clearRequestNumber = function(event) {

        if (event) {
            event.preventDefault();
            event.stopPropagation();
        }

        c.data.filters.requestNumber = "";
        c.activeSuggestionIndex = -1;

        c.filterRequestNumberSuggestions();
        c.requestDropdownOpen = true;
    };

    c.handleRequestNumberKeydown = function(event) {

        if (!event) {
            return;
        }

        var keyCode =
            event.which || event.keyCode;

        /*
         * Down arrow.
         */
        if (keyCode == 40) {

            event.preventDefault();

            if (!c.requestDropdownOpen) {
                c.openRequestNumberSuggestions();
            }

            if (
                c.filteredRequestNumberSuggestions.length
            ) {
                c.activeSuggestionIndex++;

                if (
                    c.activeSuggestionIndex >=
                    c.filteredRequestNumberSuggestions.length
                ) {
                    c.activeSuggestionIndex = 0;
                }
            }

            return;
        }

        /*
         * Up arrow.
         */
        if (keyCode == 38) {

            event.preventDefault();

            if (!c.requestDropdownOpen) {
                c.openRequestNumberSuggestions();
            }

            if (
                c.filteredRequestNumberSuggestions.length
            ) {
                c.activeSuggestionIndex--;

                if (
                    c.activeSuggestionIndex < 0
                ) {
                    c.activeSuggestionIndex =
                        c.filteredRequestNumberSuggestions.length - 1;
                }
            }

            return;
        }

        /*
         * Enter.
         */
        if (keyCode == 13) {

            event.preventDefault();

            if (
                c.requestDropdownOpen &&
                c.activeSuggestionIndex >= 0 &&
                c.filteredRequestNumberSuggestions[
                    c.activeSuggestionIndex
                ]
            ) {
                c.selectRequestNumber(
                    c.filteredRequestNumberSuggestions[
                        c.activeSuggestionIndex
                    ],
                    event
                );
            } else {
                c.requestDropdownOpen = false;
                c.search();
            }

            return;
        }

        /*
         * Escape.
         */
        if (keyCode == 27) {

            event.preventDefault();

            c.requestDropdownOpen = false;
            c.activeSuggestionIndex = -1;
        }
    };

    c.handleOutsideClick = function() {
        c.requestDropdownOpen = false;
        c.activeSuggestionIndex = -1;
    };

    /*
     * TAB / FILTER METHODS
     */

    c.selectStatus = function(status) {

        if (c.data.loading) {
            return;
        }

        c.clearMessages();

        c.selectedRecord = null;
        c.requestDropdownOpen = false;

        c.data.selectedStatus = status;

        /*
         * Clear request number because request-number
         * suggestions are different for every tab.
         */
        c.data.filters.requestNumber = "";

        c.search();
    };

    c.selectRecord = function(record) {

        if (!record) {
            return;
        }

        c.selectedRecord = record;

        c.selectedRecord.commentValidationError =
            false;
    };

    c.clearSelectedRecord = function() {
        c.selectedRecord = null;
    };

    c.search = function() {

        if (c.data.loading) {
            return;
        }

        c.clearMessages();

        c.selectedRecord = null;
        c.requestDropdownOpen = false;
        c.data.loading = true;

        c.server.get(
            c.getRequestParameters("search")
        ).then(
            function(response) {

                c.updateResponse(response);
                c.data.loading = false;

            },
            function() {

                c.data.loading = false;

                c.data.errorMessage =
                    "Unable to load learning approvals.";
            }
        );
    };

    c.resetFilters = function() {

        if (c.data.loading) {
            return;
        }

        c.data.filters = {
            requestNumber: "",
            courseType: "",
            courseFormat: "",
            country: ""
        };

        c.data.sortOrder = "asc";
        c.requestDropdownOpen = false;

        c.search();
    };

    c.refresh = function() {

        if (!c.data.loading) {
            c.search();
        }
    };

    c.sortRecords = function() {

        if (c.data.loading) {
            return;
        }

        c.data.sortOrder =
            c.data.sortOrder == "asc"
                ? "desc"
                : "asc";

        c.search();
    };

    /*
     * APPROVE
     */

    c.approve = function(record) {

        if (
            !record ||
            record.processing
        ) {
            return;
        }

        c.clearMessages();

        var comments =
            trimValue(
                record.actionComments
            );

        if (!comments) {

            record.commentValidationError =
                true;

            return;
        }

        record.processing = true;

        record.commentValidationError =
            false;

        var parameters =
            c.getRequestParameters(
                "approve"
            );

        parameters.approval_sys_id =
            record.approval_sys_id;

        parameters.actionComments =
            comments;

        c.server.get(parameters).then(
            function(response) {

                var result =
                    response.data || {};

                if (result.errorMessage) {

                    record.processing = false;

                    c.data.errorMessage =
                        result.errorMessage;

                    return;
                }

                c.updateResponse(response);

            },
            function() {

                record.processing = false;

                c.data.errorMessage =
                    "Unable to approve the learning application.";
            }
        );
    };

    /*
     * REJECT
     */

    c.reject = function(record) {

        if (
            !record ||
            record.processing
        ) {
            return;
        }

        c.clearMessages();

        var comments =
            trimValue(
                record.actionComments
            );

        if (!comments) {

            record.commentValidationError =
                true;

            return;
        }

        record.processing = true;

        record.commentValidationError =
            false;

        var parameters =
            c.getRequestParameters(
                "reject"
            );

        parameters.approval_sys_id =
            record.approval_sys_id;

        parameters.actionComments =
            comments;

        c.server.get(parameters).then(
            function(response) {

                var result =
                    response.data || {};

                if (result.errorMessage) {

                    record.processing = false;

                    c.data.errorMessage =
                        result.errorMessage;

                    return;
                }

                c.updateResponse(response);

            },
            function() {

                record.processing = false;

                c.data.errorMessage =
                    "Unable to reject the learning application.";
            }
        );
    };

    /*
     * REPORT DOWNLOAD
     */

    c.downloadReport = function() {

        if (
            c.data.downloading ||
            c.data.loading
        ) {
            return;
        }

        c.clearMessages();

        c.data.downloading = true;

        c.server.get({
            action: "download_report"
        }).then(
            function(response) {

                var result =
                    response.data || {};

                c.data.downloading = false;

                c.data.successMessage =
                    result.successMessage || "";

                c.data.errorMessage =
                    result.errorMessage || "";

                if (
                    !result.downloadReady ||
                    !result.fileContent
                ) {
                    if (!c.data.errorMessage) {
                        c.data.errorMessage =
                            "The report could not be generated.";
                    }

                    return;
                }

                createDownload(
                    result.fileContent,
                    result.fileName ||
                    "ASEAN_Learning_Approval_Report.csv"
                );

            },
            function() {

                c.data.downloading = false;

                c.data.errorMessage =
                    "Unable to generate the approval report.";
            }
        );
    };

    function createDownload(
        csvContent,
        fileName
    ) {

        try {

            var blob =
                new $window.Blob(
                    ["\uFEFF" + csvContent],
                    {
                        type:
                            "text/csv;charset=utf-8"
                    }
                );

            var urlApi =
                $window.URL ||
                $window.webkitURL;

            var objectUrl =
                urlApi.createObjectURL(blob);

            var link =
                $document[0].createElement("a");

            link.href = objectUrl;
            link.download = fileName;
            link.style.display = "none";

            $document[0].body.appendChild(link);

            link.click();

            $timeout(function() {

                if (link.parentNode) {
                    link.parentNode.removeChild(link);
                }

                urlApi.revokeObjectURL(objectUrl);

            }, 1000);

        } catch (error) {

            c.data.errorMessage =
                "The browser could not download the report.";
        }
    }

    function trimValue(value) {

        return String(
            value || ""
        ).replace(
            /^\s+|\s+$/g,
            ""
        );
    }
};

sp_widget.css:
.learning-widget {
  position: relative;
  min-height: 650px;
  overflow: visible;
  color: #222;
  background: #fff;
  border: 1px solid #333;
  font-family: Arial, Helvetica, sans-serif;
}

.widget-header {
  min-height: 65px;
  padding: 12px 15px 8px;
  background: #fff;
}

.widget-header h2 {
  display: inline-block;
  margin: 0;
  padding: 0 5px 8px;
  color: #ec6608;
  border-bottom: 3px solid #ec6608;
  font-size: 26px;
  font-weight: 600;
}

.stage-selection {
  display: flex;
  align-items: center;
  min-height: 52px;
  padding: 8px 15px;
  background: #fff;
  border-top: 4px solid #111;
  border-bottom: 1px solid #bdbdbd;
}

.stage-label {
  flex: 0 0 125px;
  font-size: 14px;
  text-decoration: underline;
}

.stage-tabs {
  display: flex;
  flex: 1;
  gap: 28px;
}

.stage-tab {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  flex: 1;
  max-width: 245px;
  min-height: 36px;
  padding: 5px 15px;
  color: #16415c;
  background: #eee;
  border: 0;
  border-radius: 7px;
  cursor: pointer;
  font-size: 14px;
  font-weight: 600;
}

.stage-tab:hover:not([disabled]) {
  background: #d9d9d9;
}

.stage-tab.active-stage {
  color: #fff;
  background: #f36f21;
}

.stage-tab[disabled] {
  cursor: not-allowed;
  opacity: 0.65;
}

.approval-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 23px;
  height: 23px;
  padding: 0 6px;
  color: #fff;
  background: #68737d;
  border-radius: 12px;
  font-size: 11px;
  font-weight: bold;
}

.active-stage .approval-count {
  color: #f36f21;
  background: #fff;
}

.toolbar {
  display: flex;
  align-items: stretch;
  min-height: 155px;
  overflow: visible;
  background: #e5e5e5;
  border-bottom: 1px solid #bdbdbd;
}

.download-section {
  flex: 0 0 145px;
  padding: 12px 10px;
}

.download-btn {
  width: 120px;
  min-height: 34px;
  padding: 6px 10px;
  color: #fff;
  background: #2ea94f;
  border: 0;
  font-size: 12px;
  font-weight: bold;
}

.download-btn:hover {
  background: #258d41;
}

.download-btn[disabled] {
  cursor: not-allowed;
  opacity: 0.65;
}

.download-btn i {
  margin-right: 6px;
}

.download-help {
  width: 120px;
  margin-top: 6px;
  color: #666;
  font-size: 10px;
  text-align: center;
}

.filters-container {
  flex: 1;
  padding: 10px 5px;
  overflow: visible;
}

.filter-row {
  display: flex;
  gap: 25px;
  margin-bottom: 8px;
  overflow: visible;
}

.filter-group {
  display: flex;
  align-items: center;
  flex: 1;
  min-width: 250px;
}

.filter-group label {
  flex: 0 0 115px;
  margin: 0;
  padding-right: 8px;
  font-size: 13px;
  font-weight: normal;
  text-align: right;
  text-decoration: underline;
}

.filter-group .form-control {
  flex: 1;
  height: 31px;
  padding: 4px 8px;
  color: #333;
  background: #fff;
  border: 1px solid #c4c4c4;
  border-radius: 0;
  font-size: 12px;
}

.ticket-status-field {
  color: #555 !important;
  background: #f5f5f5 !important;
}

.empty-filter {
  visibility: hidden;
}

.request-number-filter {
  overflow: visible;
}

.request-typeahead {
  position: relative;
  flex: 1;
  min-width: 0;
  overflow: visible;
  z-index: 1000;
}

.request-input-wrapper {
  position: relative;
  display: flex;
  width: 100%;
}

.request-number-input {
  width: 100%;
  padding-right: 58px !important;
}

.request-dropdown-button,
.request-clear-button {
  position: absolute;
  top: 1px;
  width: 27px;
  height: 29px;
  padding: 0;
  color: #666;
  background: transparent;
  border: 0;
  z-index: 2;
}

.request-dropdown-button {
  right: 1px;
}

.request-clear-button {
  right: 28px;
}

.request-dropdown-button:hover,
.request-clear-button:hover {
  color: #f36f21;
  background: #f2f2f2;
}

.request-dropdown-button[disabled] {
  cursor: not-allowed;
  opacity: 0.5;
}

.request-suggestion-dropdown {
  position: absolute;
  top: 33px;
  left: 0;
  right: 0;
  z-index: 9999;
  max-height: 260px;
  overflow-y: auto;
  background: #fff;
  border: 1px solid #aaa;
  box-shadow: 0 5px 12px rgba(0, 0, 0, 0.22);
}

.request-suggestion-item {
  display: block;
  width: 100%;
  padding: 8px 10px;
  color: #333;
  background: #fff;
  border: 0;
  border-bottom: 1px solid #eee;
  text-align: left;
  cursor: pointer;
}

.request-suggestion-item:last-child {
  border-bottom: 0;
}

.request-suggestion-item:hover,
.request-suggestion-item.active-suggestion {
  background: #fff1e8;
}

.suggestion-number {
  display: block;
  color: #0077b5;
  font-size: 13px;
  font-weight: bold;
}

.suggestion-course {
  display: block;
  margin-top: 2px;
  color: #333;
  font-size: 11px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.suggestion-employee {
  display: block;
  margin-top: 2px;
  color: #777;
  font-size: 10px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.request-suggestion-loading,
.request-no-suggestions {
  padding: 12px 10px;
  color: #666;
  font-size: 11px;
  text-align: center;
}

.request-suggestion-loading i {
  margin-right: 5px;
}

.filter-button-row {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

.filter-btn {
  min-width: 90px;
  height: 31px;
  color: #fff;
  border: 0;
  font-size: 12px;
  font-weight: bold;
}

.search-btn {
  background: #008fd3;
}

.reset-btn {
  background: #777;
}

.toolbar-actions {
  display: flex;
  flex: 0 0 46px;
  flex-direction: column;
  gap: 5px;
  padding: 10px 5px 8px 0;
}

.icon-btn {
  width: 36px;
  height: 32px;
  padding: 0;
  color: #fff;
  background: #2ea94f;
  border: 0;
  font-size: 17px;
}

.widget-message {
  margin: 10px 13px;
  padding: 9px 12px;
}

.loading-message {
  padding: 50px 20px;
  text-align: center;
}

.approval-workspace {
  display: flex;
  min-height: 470px;
  padding: 12px 13px 75px;
}

.approval-list-panel {
  flex: 0 0 35%;
  min-width: 290px;
  max-width: 410px;
  background: #f5f5f5;
  border: 1px solid #d5d5d5;
}

.list-panel-header {
  display: flex;
  justify-content: space-between;
  padding: 10px 14px;
  background: #eee;
  font-weight: bold;
}

.list-record-count {
  min-width: 25px;
  padding: 4px 7px;
  color: #fff;
  background: #68737d;
  border-radius: 13px;
  text-align: center;
}

.approval-cards {
  max-height: 620px;
  padding: 10px;
  overflow-y: auto;
}

.approval-card {
  display: block;
  width: 100%;
  margin-bottom: 10px;
  padding: 12px;
  background: #fff;
  border: 1px solid #d7d7d7;
  border-left: 4px solid transparent;
  text-align: left;
}

.approval-card:hover,
.approval-card.selected-card {
  border-left-color: #f36f21;
}

.card-top-row,
.card-status-row {
  display: flex;
  justify-content: space-between;
}

.card-request-number {
  color: #0077b5;
  font-weight: bold;
}

.card-course-title {
  margin: 8px 0;
  font-weight: bold;
}

.card-detail-row {
  display: grid;
  grid-template-columns: 95px 1fr;
  min-height: 22px;
  font-size: 11px;
}

.card-label {
  font-weight: bold;
}

.card-status {
  padding: 3px 8px;
  color: #fff;
  background: #f36f21;
  border-radius: 10px;
  font-size: 10px;
}

.approval-detail-panel {
  flex: 1;
  border: 1px solid #d5d5d5;
  border-left: 0;
}

.detail-empty-state {
  min-height: 470px;
  padding: 120px 35px;
  text-align: center;
}

.empty-state-icon {
  color: #f36f21;
  font-size: 42px;
}

.empty-state-title {
  margin-top: 12px;
  font-size: 18px;
  font-weight: bold;
}

.empty-state-text {
  margin-top: 8px;
  color: #666;
}

.selected-record-header {
  display: flex;
  justify-content: space-between;
  padding: 10px 16px;
  background: #f4f4f4;
}

.selected-record-number {
  color: #0077b5;
  font-weight: bold;
}

.close-selected-btn {
  width: 31px;
  height: 31px;
  color: #fff;
  background: #777;
  border: 0;
  border-radius: 50%;
}

.selected-record-body {
  max-height: 620px;
  padding: 16px;
  overflow-y: auto;
}

.detail-section {
  margin-bottom: 20px;
}

.detail-section-title {
  display: inline-block;
  margin-bottom: 12px;
  border-bottom: 2px solid #222;
  font-weight: bold;
}

.summary-detail-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(190px, 1fr));
  gap: 12px 24px;
}

.summary-detail-item {
  display: grid;
  grid-template-columns: 145px 1fr;
}

.summary-detail-label {
  font-weight: bold;
}

.selected-status-badge {
  display: inline-block;
  padding: 4px 10px;
  color: #fff;
  background: #f36f21;
  border-radius: 11px;
}

.previous-comments-section {
  margin-bottom: 20px;
  padding: 14px 16px;
  background: #f7f7f7;
  border: 1px solid #d5d5d5;
}

.previous-comment-card {
  margin-top: 12px;
  overflow: hidden;
  background: #fff;
  border: 1px solid #d7d7d7;
}

.previous-comment-heading {
  padding: 9px 12px;
  color: #333;
  background: #eee;
  border-bottom: 1px solid #d7d7d7;
  font-size: 13px;
  font-weight: bold;
}

.previous-comment-heading i {
  margin-right: 6px;
  color: #f36f21;
}

.previous-comment-text {
  min-height: 45px;
  padding: 12px;
  color: #444;
  font-size: 13px;
  line-height: 1.5;
  white-space: pre-wrap;
  word-break: break-word;
}

.selected-comments-panel {
  padding: 15px 17px;
  background: #e9e9e9;
}

.comments-title {
  margin-bottom: 10px;
  color: #ec6608;
  font-weight: bold;
}

.mandatory-symbol {
  color: #c9302c;
}

.selected-comments-textarea {
  width: 100%;
  min-height: 105px;
  resize: vertical;
}

.comments-help {
  margin-top: 5px;
  color: #666;
  font-size: 11px;
}

.field-error {
  margin-top: 5px;
  color: #c9302c;
  font-weight: bold;
}

.selected-record-actions {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  margin-top: 12px;
}

.decision-btn {
  min-width: 105px;
  height: 33px;
  color: #fff;
  border: 0;
  font-weight: bold;
}

.approve-btn {
  background: #2ea94f;
}

.reject-btn {
  background: #d9534f;
}

.no-records-card {
  padding: 40px 20px;
  color: #666;
  text-align: center;
}

.no-records-card i {
  margin-bottom: 10px;
  color: #f36f21;
  font-size: 30px;
}

.back-section {
  position: absolute;
  bottom: 10px;
  left: 10px;
}

.back-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  color: #ec6608;
  border: 2px solid #ec6608;
  border-radius: 50%;
  text-decoration: none;
}

@media screen and (max-width: 950px) {
  .approval-workspace {
    flex-direction: column;
  }

  .approval-list-panel,
  .approval-detail-panel {
    width: 100%;
    max-width: none;
  }

  .approval-detail-panel {
    border-left: 1px solid #d5d5d5;
  }
}

@media screen and (max-width: 800px) {
  .stage-selection,
  .toolbar,
  .filter-row {
    flex-direction: column;
  }

  .stage-tabs {
    width: 100%;
    flex-direction: column;
  }

  .stage-tab {
    max-width: none;
  }

  .request-typeahead {
    width: 100%;
  }
}

@media screen and (max-width: 650px) {
  .summary-detail-grid {
    grid-template-columns: 1fr;
  }

  .selected-record-actions {
    flex-direction: column;
  }

  .decision-btn {
    width: 100%;
  }
}

sp_widget.script:
(function() {

    var LEARNING_TABLE =
        "x_1549902_asean_0_learning_application";

    var APPROVAL_TABLE =
        "sysapproval_approver";

    /*
     * Initial widget data.
     */
    data.records = [];
    data.countries = [];
    data.courseTypes = [];
    data.courseFormats = [];
    data.requestNumberSuggestions = [];

    data.stageCounts = {
        manager: 0,
        pending_l2_approval: 0,
        pending_hr_review: 0
    };

    data.successMessage = "";
    data.errorMessage = "";

    data.downloadReady = false;
    data.fileContent = "";
    data.fileName = "";

    /*
     * Read client input.
     */
    var action =
        getInputValue("action");

    var selectedStatus =
        validateSelectedStatus(
            getInputValue("selectedStatus") ||
            "manager"
        );

    var requestNumber =
        getInputValue("requestNumber");

    var courseType =
        getInputValue("courseType");

    var courseFormat =
        getInputValue("courseFormat");

    var country =
        getInputValue("country");

    var sortOrder =
        getInputValue("sortOrder") ||
        "asc";

    if (
        sortOrder != "asc" &&
        sortOrder != "desc"
    ) {
        sortOrder = "asc";
    }

    data.selectedStatus =
        selectedStatus;

    data.sortOrder =
        sortOrder;

    data.filters = {
        requestNumber: requestNumber,
        courseType: courseType,
        courseFormat: courseFormat,
        country: country
    };

    /*
     * Download approved records
     * from the last 90 days.
     */
    if (action == "download_report") {
        generateApprovalReport();
        return;
    }

    /*
     * Approve request.
     */
    if (
        action == "approve" &&
        input &&
        input.approval_sys_id
    ) {
        processApproval(
            String(input.approval_sys_id),
            "approved",
            getInputValue("actionComments")
        );
    }

    /*
     * Reject request.
     */
    if (
        action == "reject" &&
        input &&
        input.approval_sys_id
    ) {
        processApproval(
            String(input.approval_sys_id),
            "rejected",
            getInputValue("actionComments")
        );
    }

    /*
     * Reload widget information.
     */
    loadStageCounts();
    loadFilterChoices();
    loadRequestNumberSuggestions();
    loadPendingApprovals();


    function getInputValue(name) {

        if (
            !input ||
            input[name] === undefined ||
            input[name] === null
        ) {
            return "";
        }

        return String(input[name]);
    }


    function validateSelectedStatus(status) {

        if (
            status == "manager" ||
            status == "pending_l2_approval" ||
            status == "pending_hr_review"
        ) {
            return status;
        }

        return "manager";
    }


    function isStatusForSelectedStage(status) {

        if (selectedStatus == "manager") {

            return (
                status == "submitted" ||
                status ==
                    "pending_manager_approval"
            );
        }

        return status == selectedStatus;
    }


    function getApprovalStageLabel(status) {

        if (
            status ==
            "pending_l2_approval"
        ) {
            return "Management L2";
        }

        if (
            status ==
            "pending_hr_review"
        ) {
            return "HR Learning";
        }

        return "In-Company Manager";
    }


    function loadStageCounts() {

        var approvalGR =
            new GlideRecord(
                APPROVAL_TABLE
            );

        approvalGR.addQuery(
            "approver",
            gs.getUserID()
        );

        approvalGR.addQuery(
            "state",
            "requested"
        );

        approvalGR.query();

        while (approvalGR.next()) {

            var learningGR =
                getLearningRecord(
                    approvalGR
                );

            if (!learningGR) {
                continue;
            }

            var status =
                getValueSafely(
                    learningGR,
                    "u_status"
                );

            if (
                status == "submitted" ||
                status ==
                    "pending_manager_approval"
            ) {
                data.stageCounts.manager++;

            } else if (
                status ==
                "pending_l2_approval"
            ) {
                data.stageCounts
                    .pending_l2_approval++;

            } else if (
                status ==
                "pending_hr_review"
            ) {
                data.stageCounts
                    .pending_hr_review++;
            }
        }
    }


    /*
     * Load request number suggestions.
     */
    function loadRequestNumberSuggestions() {

        var suggestions = [];
        var duplicateMap = {};

        var approvalGR =
            new GlideRecord(
                APPROVAL_TABLE
            );

        approvalGR.addQuery(
            "approver",
            gs.getUserID()
        );

        approvalGR.addQuery(
            "state",
            "requested"
        );

        approvalGR.query();

        while (approvalGR.next()) {

            var learningGR =
                getLearningRecord(
                    approvalGR
                );

            if (!learningGR) {
                continue;
            }

            var status =
                getValueSafely(
                    learningGR,
                    "u_status"
                );

            if (
                !isStatusForSelectedStage(
                    status
                )
            ) {
                continue;
            }

            var number =
                getDisplayValueSafely(
                    learningGR,
                    "number"
                );

            if (
                !number ||
                duplicateMap[number]
            ) {
                continue;
            }

            duplicateMap[number] = true;

            suggestions.push({
                value: number,
                label: number,

                courseTitle:
                    getDisplayValueSafely(
                        learningGR,
                        "u_course_title"
                    ),

                employeeName:
                    getDisplayValueSafely(
                        learningGR,
                        "u_employee_name"
                    ),

                sysId:
                    learningGR
                        .getUniqueValue()
            });
        }

        suggestions.sort(
            function(first, second) {

                var firstNumber =
                    String(
                        first.label || ""
                    ).toLowerCase();

                var secondNumber =
                    String(
                        second.label || ""
                    ).toLowerCase();

                if (
                    firstNumber <
                    secondNumber
                ) {
                    return -1;
                }

                if (
                    firstNumber >
                    secondNumber
                ) {
                    return 1;
                }

                return 0;
            }
        );

        data.requestNumberSuggestions =
            suggestions;
    }


    /*
     * Approve or reject an application.
     */
    function processApproval(
        approvalSysId,
        decision,
        actionComments
    ) {

        actionComments =
            trimValue(actionComments);

        if (!actionComments) {

            data.errorMessage =
                "Please enter the comments.";

            return;
        }

        var approvalGR =
            new GlideRecord(
                APPROVAL_TABLE
            );

        approvalGR.addQuery(
            "sys_id",
            approvalSysId
        );

        approvalGR.addQuery(
            "approver",
            gs.getUserID()
        );

        approvalGR.addQuery(
            "state",
            "requested"
        );

        approvalGR.setLimit(1);
        approvalGR.query();

        if (!approvalGR.next()) {

            data.errorMessage =
                "The approval was not found or is no longer pending.";

            return;
        }

        var learningGR =
            getLearningRecord(
                approvalGR
            );

        if (!learningGR) {

            data.errorMessage =
                "The approval is not related to a Learning Application.";

            return;
        }

        var recordStatus =
            getValueSafely(
                learningGR,
                "u_status"
            );

        if (
            !isStatusForSelectedStage(
                recordStatus
            )
        ) {

            data.errorMessage =
                "The application is no longer in the selected approval stage.";

            return;
        }

        /*
         * Save comments in the
         * stage-specific field.
         */
        if (
            selectedStatus ==
            "manager"
        ) {

            if (
                learningGR.isValidField(
                    "u_direct_manager_comments"
                )
            ) {
                learningGR.setValue(
                    "u_direct_manager_comments",
                    actionComments
                );
            }

        } else if (
            selectedStatus ==
            "pending_l2_approval"
        ) {

            if (
                learningGR.isValidField(
                    "u_l2_manager_comments"
                )
            ) {
                learningGR.setValue(
                    "u_l2_manager_comments",
                    actionComments
                );
            }

        } else if (
            selectedStatus ==
            "pending_hr_review"
        ) {

            if (
                learningGR.isValidField(
                    "u_hr_comments"
                )
            ) {
                learningGR.setValue(
                    "u_hr_comments",
                    actionComments
                );
            }
        }

        var actionLabel =
            decision == "approved"
                ? "Approved"
                : "Rejected";

        var journalText =
            actionLabel +
            " by: " +
            gs.getUserDisplayName() +
            "\nApproval Stage: " +
            getApprovalStageLabel(
                selectedStatus
            ) +
            "\nComments: " +
            actionComments;

        /*
         * Write only to Additional comments.
         *
         * Standard technical field name:
         * comments
         */
        if (
            learningGR.isValidField(
                "comments"
            )
        ) {
            learningGR.comments =
                journalText;
        }

        /*
         * Fallback custom field only when
         * the standard comments field
         * does not exist.
         */
        if (
            !learningGR.isValidField(
                "comments"
            ) &&
            learningGR.isValidField(
                "u_comment"
            )
        ) {

            var existingComment =
                learningGR.getValue(
                    "u_comment"
                ) || "";

            learningGR.setValue(
                "u_comment",
                existingComment
                    ? existingComment +
                      "\n\n" +
                      journalText
                    : journalText
            );
        }

        /*
         * Rejected request moves to
         * Rejected status.
         */
        if (
            decision ==
            "rejected"
        ) {
            learningGR.setValue(
                "u_status",
                "rejected"
            );
        }

        learningGR.update();

        /*
         * Save comment on the approval
         * record itself.
         *
         * This does not update the Learning
         * Request work notes.
         */
        if (
            approvalGR.isValidField(
                "comments"
            )
        ) {
            approvalGR.comments =
                actionComments;
        }

        approvalGR.setValue(
            "state",
            decision
        );

        approvalGR.update();

        data.successMessage =
            decision == "approved"
                ? "Learning application approved successfully."
                : "Learning application rejected successfully.";
    }


    function loadPendingApprovals() {

        var records = [];

        var approvalGR =
            new GlideRecord(
                APPROVAL_TABLE
            );

        approvalGR.addQuery(
            "approver",
            gs.getUserID()
        );

        approvalGR.addQuery(
            "state",
            "requested"
        );

        approvalGR.query();

        while (approvalGR.next()) {

            var learningGR =
                getLearningRecord(
                    approvalGR
                );

            if (!learningGR) {
                continue;
            }

            if (
                !matchesFilters(
                    learningGR
                )
            ) {
                continue;
            }

            records.push({

                approval_sys_id:
                    approvalGR
                        .getUniqueValue(),

                learning_sys_id:
                    learningGR
                        .getUniqueValue(),

                number:
                    getDisplayValueSafely(
                        learningGR,
                        "number"
                    ),

                employee_name:
                    getDisplayValueSafely(
                        learningGR,
                        "u_employee_name"
                    ),

                employee_email:
                    getDisplayValueSafely(
                        learningGR,
                        "u_employee_email"
                    ),

                country:
                    getDisplayValueSafely(
                        learningGR,
                        "u_country"
                    ),

                manager:
                    getDisplayValueSafely(
                        learningGR,
                        "u_manager_email"
                    ),

                management_l2:
                    getDisplayValueSafely(
                        learningGR,
                        "u_management_l2"
                    ),

                l2_required:
                    getDisplayValueSafely(
                        learningGR,
                        "manager_approval_l2_required"
                    ),

                course_title:
                    getDisplayValueSafely(
                        learningGR,
                        "u_course_title"
                    ),

                course_type:
                    getDisplayValueSafely(
                        learningGR,
                        "u_course_type"
                    ),

                course_format:
                    getDisplayValueSafely(
                        learningGR,
                        "u_course_format"
                    ),

                training_country:
                    getDisplayValueSafely(
                        learningGR,
                        "u_training_country"
                    ),

                training_provider:
                    getDisplayValueSafely(
                        learningGR,
                        "u_training_provider_name"
                    ),

                course_start_date:
                    getDisplayValueSafely(
                        learningGR,
                        "course_start_date"
                    ),

                course_end_date:
                    getDisplayValueSafely(
                        learningGR,
                        "u_course_end_date"
                    ),

                training_hours:
                    getDisplayValueSafely(
                        learningGR,
                        "u_total_training_hours"
                    ),

                currency:
                    getDisplayValueSafely(
                        learningGR,
                        "currency"
                    ),

                course_fee:
                    getDisplayValueSafely(
                        learningGR,
                        "u_course_fee"
                    ),

                other_expenses:
                    getDisplayValueSafely(
                        learningGR,
                        "u_other_expenses"
                    ),

                total_cost:
                    getDisplayValueSafely(
                        learningGR,
                        "u_total_cost"
                    ),

                ticket_status:
                    getDisplayValueSafely(
                        learningGR,
                        "u_status"
                    ),

                approval_state:
                    approvalGR
                        .getDisplayValue(
                            "state"
                        ),

                direct_manager_comments:
                    getDisplayValueSafely(
                        learningGR,
                        "u_direct_manager_comments"
                    ),

                l2_manager_comments:
                    getDisplayValueSafely(
                        learningGR,
                        "u_l2_manager_comments"
                    ),

                hr_comments:
                    getDisplayValueSafely(
                        learningGR,
                        "u_hr_comments"
                    ),

                actionComments: "",
                commentValidationError: false,
                processing: false
            });
        }

        records.sort(
            function(
                firstRecord,
                secondRecord
            ) {

                var first =
                    String(
                        firstRecord.number ||
                        ""
                    ).toLowerCase();

                var second =
                    String(
                        secondRecord.number ||
                        ""
                    ).toLowerCase();

                if (first < second) {
                    return sortOrder ==
                        "asc" ? -1 : 1;
                }

                if (first > second) {
                    return sortOrder ==
                        "asc" ? 1 : -1;
                }

                return 0;
            }
        );

        data.records = records;
    }


    function matchesFilters(
        learningGR
    ) {

        var status =
            getValueSafely(
                learningGR,
                "u_status"
            );

        if (
            !isStatusForSelectedStage(
                status
            )
        ) {
            return false;
        }

        if (requestNumber) {

            var number =
                getDisplayValueSafely(
                    learningGR,
                    "number"
                );

            if (
                !containsIgnoreCase(
                    number,
                    requestNumber
                )
            ) {
                return false;
            }
        }

        if (
            courseType &&
            getValueSafely(
                learningGR,
                "u_course_type"
            ) != courseType
        ) {
            return false;
        }

        if (
            courseFormat &&
            getValueSafely(
                learningGR,
                "u_course_format"
            ) != courseFormat
        ) {
            return false;
        }

        if (
            country &&
            getValueSafely(
                learningGR,
                "u_country"
            ) != country
        ) {
            return false;
        }

        return true;
    }


    function loadFilterChoices() {

        var countryMap = {};
        var courseTypeMap = {};
        var courseFormatMap = {};

        var approvalGR =
            new GlideRecord(
                APPROVAL_TABLE
            );

        approvalGR.addQuery(
            "approver",
            gs.getUserID()
        );

        approvalGR.addQuery(
            "state",
            "requested"
        );

        approvalGR.query();

        while (approvalGR.next()) {

            var learningGR =
                getLearningRecord(
                    approvalGR
                );

            if (!learningGR) {
                continue;
            }

            var status =
                getValueSafely(
                    learningGR,
                    "u_status"
                );

            if (
                !isStatusForSelectedStage(
                    status
                )
            ) {
                continue;
            }

            addChoice(
                data.countries,
                countryMap,
                getValueSafely(
                    learningGR,
                    "u_country"
                ),
                getDisplayValueSafely(
                    learningGR,
                    "u_country"
                )
            );

            addChoice(
                data.courseTypes,
                courseTypeMap,
                getValueSafely(
                    learningGR,
                    "u_course_type"
                ),
                getDisplayValueSafely(
                    learningGR,
                    "u_course_type"
                )
            );

            addChoice(
                data.courseFormats,
                courseFormatMap,
                getValueSafely(
                    learningGR,
                    "u_course_format"
                ),
                getDisplayValueSafely(
                    learningGR,
                    "u_course_format"
                )
            );
        }

        sortChoices(data.countries);
        sortChoices(data.courseTypes);
        sortChoices(data.courseFormats);
    }


    /*
     * Download only approved records
     * from the previous 90 days.
     */
    function generateApprovalReport() {

        data.downloadReady = false;
        data.fileContent = "";
        data.fileName = "";

        try {

            var rows = [];
            var count = 0;

            var cutoffDate =
                new GlideDateTime();

            cutoffDate.addDaysUTC(-90);

            rows.push(
                createCsvRow([
                    "Number",
                    "Employee Name",
                    "Employee Email",
                    "Country",
                    "Manager",
                    "Management L2",
                    "Course Title",
                    "Course Type",
                    "Course Format",
                    "Learning Request Status",
                    "Approval Stage",
                    "Approval Decision",
                    "Decision Date",
                    "Approver",
                    "Approval Comments"
                ])
            );

            var approvalGR =
                new GlideRecord(
                    APPROVAL_TABLE
                );

            approvalGR.addQuery(
                "approver",
                gs.getUserID()
            );

            approvalGR.addQuery(
                "state",
                "approved"
            );

            approvalGR.addQuery(
                "sys_updated_on",
                ">=",
                cutoffDate
            );

            approvalGR.orderByDesc(
                "sys_updated_on"
            );

            approvalGR.query();

            while (approvalGR.next()) {

                var learningGR =
                    getLearningRecord(
                        approvalGR
                    );

                if (!learningGR) {
                    continue;
                }

                count++;

                rows.push(
                    createCsvRow([

                        getDisplayValueSafely(
                            learningGR,
                            "number"
                        ),

                        getDisplayValueSafely(
                            learningGR,
                            "u_employee_name"
                        ),

                        getDisplayValueSafely(
                            learningGR,
                            "u_employee_email"
                        ),

                        getDisplayValueSafely(
                            learningGR,
                            "u_country"
                        ),

                        getDisplayValueSafely(
                            learningGR,
                            "u_manager_email"
                        ),

                        getDisplayValueSafely(
                            learningGR,
                            "u_management_l2"
                        ),

                        getDisplayValueSafely(
                            learningGR,
                            "u_course_title"
                        ),

                        getDisplayValueSafely(
                            learningGR,
                            "u_course_type"
                        ),

                        getDisplayValueSafely(
                            learningGR,
                            "u_course_format"
                        ),

                        getDisplayValueSafely(
                            learningGR,
                            "u_status"
                        ),

                        getReportApprovalStage(
                            learningGR,
                            approvalGR
                        ),

                        approvalGR
                            .getDisplayValue(
                                "state"
                            ),

                        approvalGR
                            .getDisplayValue(
                                "sys_updated_on"
                            ),

                        approvalGR
                            .getDisplayValue(
                                "approver"
                            ),

                        getApprovalComments(
                            approvalGR
                        )
                    ])
                );
            }

            if (count === 0) {

                data.errorMessage =
                    "No approved records were found for the last 90 days.";

                return;
            }

            data.fileContent =
                rows.join("\r\n");

            var dateText =
                String(
                    new GlideDateTime()
                        .getLocalDate()
                        .toString()
                )
                .split("-")
                .join("");

            data.fileName =
                "ASEAN_Approved_Records_Last_90_Days_" +
                dateText +
                ".csv";

            data.downloadReady = true;

            data.successMessage =
                count +
                " approved record(s) from the last 90 days exported.";

        } catch (error) {

            data.errorMessage =
                "Unable to generate report: " +
                error.message;

            gs.error(
                "ASEAN Approval Widget report error: " +
                error.message
            );
        }
    }


    function getReportApprovalStage(
        learningGR,
        approvalGR
    ) {

        var shortDescription = "";

        if (
            approvalGR.isValidField(
                "short_description"
            )
        ) {
            shortDescription =
                approvalGR
                    .getDisplayValue(
                        "short_description"
                    ) || "";
        }

        var descriptionLower =
            String(shortDescription)
                .toLowerCase();

        if (
            descriptionLower
                .indexOf("hr") > -1
        ) {
            return "HR Learning";
        }

        if (
            descriptionLower
                .indexOf("l2") > -1
        ) {
            return "Management L2";
        }

        if (
            descriptionLower
                .indexOf("manager") > -1
        ) {
            return "In-Company Manager";
        }

        var approverSysId =
            approvalGR.getValue(
                "approver"
            );

        var directManager =
            getValueSafely(
                learningGR,
                "u_direct_manager"
            );

        if (
            !directManager &&
            learningGR.isValidField(
                "u_manager_email"
            ) &&
            learningGR
                .getElement(
                    "u_manager_email"
                )
                .getED()
                .getInternalType() ==
                "reference"
        ) {
            directManager =
                getValueSafely(
                    learningGR,
                    "u_manager_email"
                );
        }

        var l2Manager =
            getValueSafely(
                learningGR,
                "u_management_l2"
            );

        if (
            approverSysId &&
            approverSysId ==
                l2Manager
        ) {
            return "Management L2";
        }

        if (
            approverSysId &&
            approverSysId ==
                directManager
        ) {
            return "In-Company Manager";
        }

        return "Approval";
    }


    function getLearningRecord(
        approvalGR
    ) {

        var learningSysId =
            approvalGR.getValue(
                "sysapproval"
            );

        if (!learningSysId) {

            learningSysId =
                approvalGR.getValue(
                    "document_id"
                );
        }

        if (!learningSysId) {
            return null;
        }

        var learningGR =
            new GlideRecord(
                LEARNING_TABLE
            );

        if (
            !learningGR.get(
                learningSysId
            )
        ) {
            return null;
        }

        return learningGR;
    }


    function getApprovalComments(
        approvalGR
    ) {

        if (
            approvalGR.isValidField(
                "comments"
            )
        ) {
            return (
                approvalGR
                    .getDisplayValue(
                        "comments"
                    ) || ""
            );
        }

        return "";
    }


    function addChoice(
        collection,
        map,
        value,
        label
    ) {

        if (
            !value ||
            map[value]
        ) {
            return;
        }

        map[value] = true;

        collection.push({
            value: value,
            label: label || value
        });
    }


    function sortChoices(
        collection
    ) {

        collection.sort(
            function(
                firstChoice,
                secondChoice
            ) {

                var first =
                    String(
                        firstChoice.label ||
                        ""
                    ).toLowerCase();

                var second =
                    String(
                        secondChoice.label ||
                        ""
                    ).toLowerCase();

                if (first < second) {
                    return -1;
                }

                if (first > second) {
                    return 1;
                }

                return 0;
            }
        );
    }


    function containsIgnoreCase(
        source,
        search
    ) {

        return (
            String(source || "")
                .toLowerCase()
                .indexOf(
                    String(search || "")
                        .toLowerCase()
                ) > -1
        );
    }


    function trimValue(value) {

        return String(value || "")
            .replace(
                /^\s+|\s+$/g,
                ""
            );
    }


    function getValueSafely(
        record,
        fieldName
    ) {

        if (
            !record ||
            !record.isValidField(
                fieldName
            )
        ) {
            return "";
        }

        return (
            record.getValue(
                fieldName
            ) || ""
        );
    }


    function getDisplayValueSafely(
        record,
        fieldName
    ) {

        if (
            !record ||
            !record.isValidField(
                fieldName
            )
        ) {
            return "";
        }

        return (
            record.getDisplayValue(
                fieldName
            ) || ""
        );
    }


    function escapeCsv(value) {

        value =
            String(value || "");

        value =
            value
                .split("\r\n")
                .join(" ");

        value =
            value
                .split("\n")
                .join(" ");

        value =
            value
                .split("\r")
                .join(" ");

        /*
         * Prevent CSV formula injection.
         */
        var firstCharacter =
            value.length
                ? value.charAt(0)
                : "";

        if (
            firstCharacter == "=" ||
            firstCharacter == "+" ||
            firstCharacter == "-" ||
            firstCharacter == "@"
        ) {
            value = "'" + value;
        }

        value =
            value
                .split('"')
                .join('""');

        return '"' + value + '"';
    }


    function createCsvRow(values) {

        var row = [];

        for (
            var index = 0;
            index < values.length;
            index++
        ) {
            row.push(
                escapeCsv(
                    values[index]
                )
            );
        }

        return row.join(",");
    }

})();
